"""Builds docs/handbook/lesson-9.html. Every code block is cut from the real repo by anchor text,
so the page cannot show code that does not exist; a missing anchor fails the build."""
import html, os, pathlib, re, subprocess
here = pathlib.Path(__file__).resolve()
root = pathlib.Path(os.environ.get("NOON_ROOT") or (here.parents[2] if (here.parents[2] / "SPEC.md").exists() else pathlib.Path.cwd()))
out = pathlib.Path(os.environ.get("NOON_OUT") or root / "docs/handbook")
commit = subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=root, capture_output=True, text=True).stdout.strip()

def cut(path, start, end=None, include_end=False):
    src = (root / path).read_text()
    i = src.index(start)
    j = len(src) if end is None else src.index(end, i + len(start)) + (len(end) if include_end else 0)
    body = src[i:j].rstrip()
    return (f'<p class="label">From <span class="mono">{path}</span></p>'
            f'<div class="scroll"><pre><code>{html.escape(body)}</code></pre></div>')

def shell(title, body):
    return f'<p class="label">{title}</p><div class="scroll"><pre class="out"><code>{body}</code></pre></div>'

def vs(rows, head=("TypeScript (this repo)", "Java", "Python")):
    body = "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows)
    return f'<div class="scroll"><table><tr>{"".join(f"<th>{h}</th>" for h in head)}</tr>{body}</table></div>'

def case(title, body): return f'<div class="break"><p class="label">Case study · found by review, by a learning test, or by a test that was written to refute a claim</p><p><strong>{title}</strong></p>{body}</div>'
def note(body): return f'<p class="note">{body}</p>'
m = lambda s: f"<span class='mono'>{s}</span>"

S = []
def section(sid, title, *parts): S.append((sid, title, "".join(parts)))

section("map", "The map: what a job is promised here, and who keeps the promise",
  "<p>Epic 3 made a job a row: the <code>jobs</code> table is the run, the preview and the ship, and the queue only tells a worker to look (SPEC §2.9). Epics 4 to 8 built on that without asking what happens when the parts around the row misbehave: a browser that presses twice, a worker that dies with a job half done, a Redis that is flushed, a page reloaded mid-run, a tenant that asks for more than its share. Epic 9 asks those five questions and answers each one from the same place, the row in Postgres. <strong>A press is one job</strong> (F27): a retry with the same <code>Idempotency-Key</code> is answered with the job the first press made, however many arrive at once, because the key is claimed with the row's primary key before the job exists. <strong>A dead worker's job runs again, once</strong> (F28): a running job heartbeats its row every second, a sweep puts a silent one back in the queue, and the attempt number fences a worker that was only slow. <strong>Losing Redis loses nothing</strong> (F28, §4): the sweep rebuilds the queue from whatever Postgres still calls <code>queued</code>, and no code changed to make that true, only the proof was missing. <strong>Progress is a column</strong> (F30): the run's steps ride the row, written by the attempt that holds it, read by whoever asks. <strong>Limits are counted where the work is</strong> (F31): one upsert in the run's own transaction for AI runs, and the same upsert for every HTTP route, so every api instance shares the count and nothing fails open.</p>",
  vs([("1", m("packages/db/migrations/0018_idempotency_keys.sql"), m("packages/db/src/index.ts"), "<code>idempotency_keys</code> with <code>primary key (org_id, user_id, key)</code>; <code>withKey</code> claims with <code>insert ... on conflict do nothing</code> in a transaction, makes the job, records its id; the loser waits on the row and answers from the job's row as it now is; 422 for the same key with another request"),
      ("2", m("packages/db/migrations/0019_job_heartbeat.sql"), m("apps/worker/src/worker.ts"), "<code>heartbeat_at</code> and <code>attempts</code>; <code>claim()</code> is the next attempt; a 1 s beat that also answers cancel; <code>requeueStale</code> in one statement with <code>for update skip locked</code>; <code>finish</code> and <code>report</code> fenced by the attempt"),
      ("3", m("apps/worker/src/ai.ts"), m("apps/worker/src/tools.ts"), "<code>replayIds</code>: the n-th node id and the n-th op id are functions of (job, n, the op); <code>add_node</code> on a node that already exists with the same shape is <em>done</em>, not refused; the room's (sender, opId) dedupe from E6.1 answers a replayed op with its original seq"),
      ("4", m("scripts/chaos/redis-wipe-rebuild.ts"), m("scripts/chaos/rebuild.ts"), "no production change; two rounds (FLUSHALL, restart) under running and waiting runs and an open room; the judge asks: every run succeeded with <code>attempts = 1</code>, every step journaled once, the lease back under a larger token that the journal's fence names"),
      ("5", m("apps/worker/src/progress.ts"), m("apps/web/src/AiPanel.tsx"), "the steps on <code>jobs.output</code>, the last 50, written in order and awaited before the row is finished; the model's argument stripped of <code>\\p{C}</code> and cut to 80; <code>GET /documents/:id/run</code> for the newest run; the panel polls it and a reload picks it up"),
      ("6", m("packages/db/migrations/0020_rate_limits.sql"), m("packages/db/src/limit.ts"), "<code>rate_limits (key, win, hits)</code>; <code>take()</code> is one upsert with <code>greatest(win)</code>; the hit inside <code>createRun</code>'s transaction, before the insert, rolled back with a refused run; <code>Retry-After</code> from the database's clock; the usage view in one REPEATABLE READ snapshot"),
      ("7", m("apps/api/src/app.ts"), m("apps/api/src/client-address.ts"), "every route but the probes and the webhook: <code>user:&lt;id&gt;</code>, else <code>address:&lt;client&gt;</code>; <code>mint:&lt;user&gt;</code> before the document lookup; sign-in per email under a SHA-256; the client address as the rightmost <code>X-Forwarded-For</code> entry a trusted proxy vouched for")], head=("Step", "Where", "And", "What happens")),
  "<p>Four ideas carry the epic, and they are what an interviewer will press on. <strong>Exactly-once is a property of the whole, never of a delivery</strong> (sections 1 and 3): messages arrive at least once or at most once, never exactly once, so \"once\" is manufactured by an idempotent receiver: a key claimed by a primary key, an op id the room has already answered, a node the retry finds already there. The industry word is <em>effectively once</em>. <strong>A heartbeat is not a lease</strong> (section 2): lesson 7's lease said \"I may write until this time\"; a heartbeat only says \"I was alive a second ago\", and the decision to give the job away is made by whoever reads it, so a slow worker that was given up on must be <em>fenced</em> by something the write itself checks, the attempt number. <strong>Postgres is the truth and Redis is a cache</strong> (sections 4 and 6): a queue message is a hint that a row exists, a lease is a hint that a room is owned, and a counter that must be shared and must not fail open lives beside the rows it protects. <strong>Who is asking is a trust decision</strong> (section 7): an address in a header is written by whoever sent the header, and only the hop you trust can vouch for the one before it.</p>",
  vs([("<code>Idempotency-Key</code> claimed by a primary key in the job's transaction; a replay answers from the row; 422 on a different request", "Stripe's <code>Idempotency-Key</code>: 24 h, a replay returns the saved response, different parameters are an <code>idempotency_error</code>; Spring has nothing built in (a table and a filter, as here)", "Stripe's Python SDK sends one per request; Django has nothing built in; Celery's <code>task_id</code> dedupes the message, not the effect"),
      ("a 1 s heartbeat on the row, a 15 s stale sweep, <code>attempts</code> as a fence", "Spring Batch's <code>JobRepository</code> marks a step <code>STARTED</code> and a restart must be told to <code>allowStartIfComplete</code>; Quartz's misfire handling; SQS's visibility timeout is the same idea from the broker's side", "Celery <code>acks_late</code> + <code>visibility_timeout</code> (a slow task is redelivered and runs twice); Sidekiq Pro's super_fetch; both re-run, neither fences"),
      ("ids that are a function of (job, step, op), so a replay is deduplicated by the room", "Kafka's idempotent producer: a sequence number per (producer, partition), the broker drops what it has seen", "the same idea; Celery's tasks are asked to be idempotent and given no help"),
      ("a fixed window in Postgres, one upsert, <code>Retry-After</code> to the second", "Bucket4j and resilience4j's <code>RateLimiter</code> are in-process (per instance); a shared count needs Redis or JDBC", "django-ratelimit: cache-backed fixed windows, failing open when the cache is away by default"),
      ("<code>X-Forwarded-For</code> read from the right, only past a trusted proxy", "Spring's <code>ForwardedHeaderFilter</code> believes the header from anyone unless you configure trusted proxies; Tomcat's <code>RemoteIpValve</code> has <code>internalProxies</code>", "Django's <code>REMOTE_ADDR</code> is the peer; django-ipware guesses from the left unless told otherwise; gunicorn's <code>forwarded_allow_ips</code>")], head=("This repo", "Java world", "Python world")))

section("keys", "1 · Idempotency keys: the claim is the row, and the answer is the job as it now is",
  "<p>A browser presses \"Ask the AI\", the request leaves, and the answer never comes back: a proxy timed out, the tab lost its network, the api returned a 502 while restarting. The person presses again. Without a key, two runs exist (or one 409 and a confused person); with one, the retry is <em>the same request</em> and gets the same answer. Stripe's version of this is the model: the client mints a key per operation, the server stores what it did under the key for 24 hours, and a replay returns the stored result. The design question is where the key lives and how two requests carrying it <em>at the same moment</em> are told apart, because a retry is often a duplicate on the wire rather than a person's second press, and both arrive within milliseconds.</p>",
  cut("packages/db/migrations/0018_idempotency_keys.sql", "-- E9.1 (F27)"),
  "<p>Read the primary key first: <code>(org_id, user_id, key)</code>. The key belongs to a user in an org, so a key from one tenant can never resolve to another tenant's job, and the same string from two users is two keys (the test \"a key belongs to its user in its org\" makes bob use ann's key and asks for his own job, then makes him use it on <em>her</em> document and asks 404). The <code>request</code> column stores what was asked: the queue, the document, the input. That is what lets the same key with a different instruction be refused as <code>422 idempotency_key_reused</code> rather than silently answered with the wrong job, which is what Stripe does too (an <code>idempotency_error</code> when the parameters differ). <code>job_id</code> is nullable, and the comment says why: the key is claimed <em>before</em> the job exists, inside the transaction that will make it, and nobody outside that transaction ever sees the null.</p>",
  cut("packages/contracts/src/index.ts", "/**\n * F27: the `Idempotency-Key` header", "/** Newlines and tabs"),
  cut("apps/api/src/app.ts", "/** F27: the request's `Idempotency-Key`", "function pageQuery"),
  "<p>A malformed key is a 400, never ignored. The tempting shape is \"if the key does not parse, proceed without one\", and it is wrong for the same reason a malformed cookie is not \"nobody\": the retry the key was meant to make safe would then make a second job, and the client would believe it was protected. Refusing is the honest answer.</p>",
  cut("packages/db/src/index.ts", "      /**\n       * F27: `make` runs in a transaction", "      /** One statement: the run, if the document"),
  "<p>This is the section's centre, and the drill plants its bug. <code>withKey</code> opens a transaction, sweeps this user's keys older than 24 hours (a ponytail named in the migration: rows of users who never return stay until they do), and then <em>claims</em> the key with <code>insert ... on conflict do nothing</code>. Under READ COMMITTED, a second transaction inserting the same primary key does not fail at once: it <strong>blocks on the first transaction's row until it commits or rolls back</strong>, then sees either a conflict (the winner committed) or a free key (the winner rolled back). That blocking is the whole mechanism. Twenty requests arrive together; one inserts and goes on to make the job; nineteen wait inside their <code>insert</code>; when the winner commits, each of the nineteen gets <code>rowCount 0</code>, reads the winner's row in <em>a statement of its own</em> (the comment says why: a statement started before the winner committed would not see it), and answers with the winner's job id. No lock was named, no retry loop written; the primary key did it.</p>",
  "<p>Then the two branches that make the key <em>safe</em> as well as unique. If <code>make</code> made no job (the document was busy, or gone), the transaction <strong>rolls back</strong>, and the claim with it: the key was never used, and the retry that follows the 409 may use it to start the next run. If it did, the job id is recorded on the key and both commit together, so a crash between \"job made\" and \"key recorded\" cannot leave a job without its key (and a replay would then make a second one). The <code>client.release(broken)</code> at the end is <code>pg</code>'s way of throwing a connection away rather than returning a possibly poisoned one to the pool.</p>",
  cut("packages/db/src/index.ts", "        createRun: async ({ documentId, instruction, createdBy, idempotencyKey, limit }) => {", "        cancelRun: async"),
  cut("apps/api/src/app.ts", "  // F27: a retry with the same Idempotency-Key answers 201", '  document.post("/runs/:runId/cancel"'),
  "<p>\"As its row now is\" is the sentence to remember. A replay is answered by <code>select * from jobs where id = $replay</code>, never from the queue's <code>add()</code> and never from a cached copy of the first response: the first test claims the run after making it and asserts the replay says <code>running</code>. Stripe stores the original response bytes; this repo stores the job's id and reads the job, because the job is the truth and the person retrying wants to know where it is now. The ship route does the same with 200 rather than 201, because a ship press may have <em>joined</em> a waiting ship rather than made one, and the key keeps naming the ship it pressed even after newer ships are queued behind it.</p>",
  cut("packages/db/src/index.ts", "        startShip: async ({ documentId, createdBy, idempotencyKey }) => {", "        async getShip(documentId)"),
  cut("packages/queue/src/index.ts", "    // jobId = our job's id", "    ping:"),
  "<p>The replay <em>enqueues again</em> (a ponytail the commit names) and it is harmless twice over: BullMQ drops an <code>add</code> for a job id it already holds, and the worker's <code>claim()</code> is <code>queued → running</code> in one statement, so a job runs at most once per claim whatever the queue says. That is the second half of \"effectively once\": the delivery may repeat; the state transition cannot.</p>",
  cut("apps/web/src/api.ts", "/**\n * F27: a POST that makes a job.", "// --- Signing in (F23)"),
  "<p>The client's half is short on purpose. One press mints one <code>crypto.randomUUID()</code>; a lost answer or a 5xx is retried once with the same key; a 4xx is not retried (the same request a moment later is refused again), and neither is a 429 (section 6). A retry loop with backoff is the upgrade; one retry is what makes the common case, a dropped connection, invisible to the person.</p>",
  cut("apps/api/src/idempotency.int.test.ts", 'test("twenty simultaneous starts with one key', 'test("twenty simultaneous ships'),
  cut("apps/api/src/idempotency.int.test.ts", 'test("a key belongs to its user in its org', 'test("a start refused as busy'),
  cut("apps/api/src/idempotency.int.test.ts", 'test("a start refused as busy does not use up its key', 'test("a key lives 24 hours'),
  vs([("<code>insert ... on conflict do nothing</code> and <code>rowCount !== 1</code>", "<code>INSERT ... ON CONFLICT</code> through JDBC; JPA's <code>persist</code> throws on a duplicate after the flush, which is too late to branch on cleanly", "<code>INSERT ... ON CONFLICT</code> with psycopg; the ORM's <code>get_or_create</code> is a look-then-insert with a retry on <code>IntegrityError</code>"),
      ("a second transaction blocking on an uncommitted row with the same primary key", "the same Postgres behaviour; with MySQL InnoDB too, with gap locks", "the same"),
      ("<code>client.release(broken)</code>: a poisoned connection is destroyed, not returned", "HikariCP evicts on <code>SQLException</code> by its own rules", "psycopg_pool's <code>putconn</code> discards a connection in a failed state"),
      ("<code>{ made: T } | { replay: string } | \"key_reused\"</code>: three outcomes as one union", "a sealed interface with three records, or an <code>Either</code>", "a <code>Union</code> of dataclasses and a <code>Literal</code>"),
      ("<code>Promise.all(Array.from({ length: 20 }, () => run(...)))</code>: twenty requests in flight at once", "an <code>ExecutorService</code> and a <code>CountDownLatch</code>", "<code>asyncio.gather</code>"),
      ("<code>crypto.randomUUID()</code> in the browser", "<code>UUID.randomUUID()</code>", "<code>uuid.uuid4()</code>")]),
  case("The key as columns on the jobs row was rejected.",
       "<p>A <code>idempotency_key</code> column with a partial unique index is the obvious shape and it fails twice. A ship press that <em>joins</em> the waiting ship makes no row and so has nowhere to keep its key, yet its replay must still answer that ship. And the key could not be claimed before the job exists, which is exactly what serialises two requests at the same moment without touching the busy-run and waiting-ship indexes: with the key on the row, the second request would race the first through those indexes instead and one of them would see a 409 that no person pressed.</p>"),
  case("A look-then-insert was rejected, and drill 2 plants it.",
       "<p><code>select ... where key = $1</code>, then <code>insert</code> if nothing was found, is what every ORM's <code>get_or_create</code> does, and under twenty concurrent requests every one of them finds nothing and inserts. The unique constraint then fails nineteen of them, and the code has to catch the error and read again, which is the same statement the design starts with, written the long way round. <code>on conflict do nothing</code> makes the claim and the check one statement, and the blocking on the uncommitted row is what a look could never give.</p>"),
  case("A refused run rolls its claim back rather than recording the refusal.",
       "<p>Stripe records every outcome under the key, including errors, so a retry of a failed request gets the same failure. That is right for a payment (the client must not be charged on a retry of a declined card) and wrong for a busy document: the person who got a 409 waits for the run to end and presses again with a retry of the same request, and a recorded refusal would answer 409 for 24 hours. So a <code>make</code> that made nothing rolls the whole transaction back, and the key is as if never sent.</p>"),
  note("<strong>The principle:</strong> a delivery is never exactly once, so make the <em>effect</em> idempotent and let the delivery repeat. The key is claimed by the database's own uniqueness, in the same transaction as the work, before the work exists, so that two claims at one moment are serialised by a row lock nobody had to name. The replay reads the truth, not a memory of the first answer. And a claim that produced nothing is undone, so the key protects the retry it was sent for and nothing else."))

section("heartbeat", "2 · Heartbeats, the stale sweep, and the attempt as a fence",
  "<p><code>kill -9</code> says nothing. A worker that is killed, or whose host is lost, or that the OOM killer takes, leaves its job's row saying <code>running</code>, and E3 built one unfinished run per document on that row: the document's next run is refused for ever, a sandbox job left running blocks the preview and keeps its container from the reaper (the E4.2b finding), a ship never ends. BullMQ has a stalled-job checker for this, and it was rejected in one sentence: Redis is not the truth, and a message can be dropped. So the job's own row says whether its worker is alive, and Postgres decides what to do about a silent one.</p>",
  cut("packages/db/migrations/0019_job_heartbeat.sql", "-- E9.2a (F28)"),
  cut("packages/db/src/index.ts", "/** `attempt`: the claim a worker holds", "  /** What this job consumed"),
  "<p>Two columns. <code>heartbeat_at</code> is the last moment a worker said \"still here\", once a second. <code>attempts</code> counts claims and does two jobs at once: it <strong>bounds</strong> the retries (a job that kills its worker every time must still end, and after three claims it fails as <code>worker_lost</code>), and it <strong>fences</strong>. The fence is the part most retry systems miss. A worker that was only slow, a 20-second GC pause, an event loop blocked by a synchronous call, a network partition from Postgres, stops beating for longer than <code>staleMs</code> and is given up on; then it wakes, finishes its work, and writes <code>succeeded</code> over a row that another worker is now running as attempt 2. Lesson 7 met the same shape with the lease token and answered it by making every write name the token; here every write names the attempt.</p>",
  cut("packages/db/src/index.ts", "      // `queue = $3`: the message says which queue it came from", "      async requeueStale(staleMs, maxAttempts) {"),
  "<p><code>claim</code> is the only way in: <code>queued → running</code>, <code>attempts + 1</code>, the first beat, in one statement that returns the row; a second message for the same job finds nothing to claim. <code>finish</code> and <code>heartbeat</code> both carry <code>and attempts = $attempt</code>: a beat from a dead attempt returns no row, which the store reads as <code>lost</code>, and a finish from one updates nothing. The beat also answers the cancel question (F10) that E3's poll used to ask, so the per-job timer does one round trip a second rather than two.</p>",
  cut("packages/db/src/index.ts", "      async requeueStale(staleMs, maxAttempts) {", "      async recordUsage("),
  "<p>The sweep is one statement, and every clause is a decision. <code>for update skip locked</code>: every worker process runs the sweep (the AI worker brings a dead sandbox worker's job back, and the other way round), and two sweeps at once must not both take a row, so each locks what it will touch and skips what another already holds; the test fires four sweeps over ten stale rows and counts ten requeues. <code>coalesce(heartbeat_at, started_at)</code>: a row left running before this migration has no beat and is judged by its start. <code>distinct on</code> for ships: of the ships of one document that went silent together only the newest may wait again, because migration 0011 allows one waiting ship per document, and the newest reads the document afresh so it ships what all of them would have. A job someone asked to cancel is not run again: it ends <code>cancelled</code>, as its worker would have ended it. And the <code>output</code> case: a sandbox's address dies with its worker, an AI run's steps are the dead attempt's (section 5), a ship's commit stays because the git peer will ask \"did Ship push this?\".</p>",
  cut("apps/worker/src/worker.ts", "  /**\n   * A running job whose last beat is older than this", "  /** Called after every sweep"),
  cut("apps/worker/src/worker.ts", "    // Claiming is the ONLY way to start", "    try {\n      const handler"),
  "<p>The worker's half. <code>mine</code> is the key every write of this attempt carries. The interval beats, and the answer drives an <code>AbortController</code>: <code>cancel</code> aborts the handler (F10, as before); <code>lost</code> aborts it too, with a warning, which is how a slow worker learns it has been given up on and stops <em>before</em> writing anything over the next attempt. A failed beat is simply tried again next second: <code>staleMs</code> is fifteen of them, so one dropped query is not a death. That ratio is the design's one tunable, and the reasoning is the same as lesson 7's ttl: many beats long, so a busy loop or a slow query is not mistaken for a crash, and if it ever is, the fence makes the mistake safe rather than fatal.</p>",
  cut("apps/worker/src/worker.ts", "  // BullMQ's own retries and stalled-job checks", "  await Promise.all(workers.map((w) => w.waitUntilReady()));"),
  cut("apps/worker/src/worker.ts", "  // Redis is not the truth (SPEC §2.9)", "  await sweep();"),
  "<p>The sweep first calls <code>requeueStale</code> and then offers every <code>queued</code> row to Redis again, in the same pass, so a job that just went stale is picked up by whichever worker is alive within one sweep. <code>sweeping ??=</code> is the memoised-promise idiom from lesson 8's dummy hash: never two sweeps from one process at once. And a refused offer must not hide the 99 behind it, which is why the loop catches per row.</p>",
  cut("packages/db/src/job-heartbeat.int.test.ts", 'test("the dead attempt\'s late writes land nowhere', 'test("a job that kills its worker every time ends'),
  cut("apps/worker/src/crash.int.test.ts", 'test("a slow worker that was given up on stops', 'test("Redis wiped under a working worker'),
  cut("packages/db/src/job-heartbeat.int.test.ts", 'test("stale ships of one document', 'test("a row left running from before heartbeats'),
  cut("packages/db/src/job-heartbeat.int.test.ts", 'test("two sweeps at once never both take a row"'),
  "<p><strong>Heartbeats against leases, once more.</strong> Lesson 7's lease was a <em>promise with a deadline</em>: the holder knows for how long it may write, renews before then, and gives up on its own clock when it cannot. A heartbeat is a <em>report with no promise</em>: the worker says it is alive and has no idea whether anyone still believes it, and the reader decides. The lease is the right tool where the holder must act alone for a while (a room ordering ops without asking anyone); the heartbeat is enough where the work can be handed to someone else and the only harm of a wrong guess is a duplicate, which the fence turns into a no-op. Both need a token in the write: the lease token in the fence claim, the attempt in <code>finish</code>. SQS's visibility timeout is a lease the broker grants; Celery's <code>acks_late</code> with a <code>visibility_timeout</code> is a heartbeat-less version of this sweep that runs the slow task twice with nothing to stop the first.</p>",
  cut("apps/worker/src/starvation.int.test.ts", "// integration:no-starvation-under-saturation", "const prefix"),
  "<p><strong>F29, no starvation.</strong> The git peer is its own process and its own loop, so a saturated AI queue cannot hold a push up; the integration test proves it in the hardest configuration, everything on one event loop, and asks a push to reach an open canvas in under five seconds while every AI slot is busy editing.</p>",
  vs([("<code>new AbortController()</code> aborted by the beat's answer", "a <code>volatile boolean</code> and <code>Thread.interrupt()</code>, or a <code>CompletableFuture.cancel</code>", "<code>asyncio.Event</code>, or a <code>threading.Event</code>"),
      ("<code>setInterval(...)</code> per running job, cleared in <code>finally</code>", "a <code>ScheduledExecutorService</code> task per job", "<code>asyncio.create_task</code> with a loop and <code>sleep</code>"),
      ("<code>sweeping ??= sweepOnce().finally(...)</code>: one sweep at a time", "a <code>ReentrantLock.tryLock()</code> around the sweep", "an <code>asyncio.Lock</code> with <code>locked()</code> checked first"),
      ("<code>for update skip locked</code>", "the same SQL; JPA's <code>@Lock(PESSIMISTIC_WRITE)</code> cannot say <code>skip locked</code> portably", "the same SQL; <code>select_for_update(skip_locked=True)</code> in Django"),
      ("<code>make_interval(secs =&gt; $1::float8 / 1000)</code>: milliseconds from the caller, an interval in SQL", "the same", "the same"),
      ("<code>distinct on (case when ... then document_id else id end)</code>: one of a group, chosen by <code>order by</code>", "a window function with <code>row_number()</code>", "the same SQL"),
      ("<code>(job.attempt)</code>: a number typed into every write's key", "a version column and <code>@Version</code>: optimistic locking is the same fence", "a version column checked in the <code>UPDATE ... WHERE</code>")]),
  case("BullMQ's stalled-job retries were rejected.",
       "<p>BullMQ can notice a worker that stopped renewing its lock and re-deliver the message. It lives in Redis, which section 4 wipes on purpose, and it knows nothing about the row: a re-delivered message for a job the row still calls <code>running</code> would be refused by <code>claim()</code> anyway. Putting the heartbeat on the row makes the row self-sufficient, and makes the stalled check the same statement on every worker.</p>"),
  case("The fence exists because of a worker that was only slow.",
       "<p>The first version had the heartbeat and the sweep and no attempt number: a job silent past 15 s was requeued, and the dead worker was assumed dead. A test then held a worker's handler open, bumped the row to attempt 2 by hand as the sweep and another claim would, and released it: the slow worker's <code>finish(\"succeeded\")</code> landed on the row attempt 2 was running, and the second worker's later finish then updated nothing because the status was no longer <code>running</code>. Naming the attempt in every write, and telling the slow worker <code>lost</code> on its next beat, made both writes land where they should: nowhere and on the row respectively.</p>"),
  case("The sweep's ship clause was found by 0011, not by design.",
       "<p>Requeueing every stale ship would have inserted two <code>queued</code> ships for one document when two had gone silent together, and the partial unique index from E5 (one waiting ship per document) would have failed the whole sweep statement, for every queue. The <code>distinct on</code> picks the newest, the older one fails as <code>worker_lost</code>, and a running ship whose document already has a ship waiting fails too, because the waiting one will ship everything. Each of those cases is one line of the heartbeat test.</p>"),
  note("<strong>The principle:</strong> a retry system has three parts and most have two. <em>Detection</em>: something says the worker is gone (a heartbeat read by a sweep). <em>Redelivery</em>: the work is offered again (the row back to <code>queued</code>, and a bound on how often). <em>Fencing</em>: the write path refuses the worker that was wrongly given up on (the attempt in every <code>update ... where</code>). Without the third, every false positive of the first is a duplicate, and the first has false positives by construction, because a timeout cannot tell slow from dead."))

section("replay", "3 · Replaying a dead attempt without a duplicate: ids that are functions of the step",
  "<p>Attempt 2 of an AI run starts its conversation with the model over, because the run's transcript is not stored (SPEC §6). The model, given the same instruction and the same document, will usually do the same first steps again, and each of them is an <code>add_node</code> the dead attempt already sent to the room. Without care the document ends with every early node twice. The tempting fix, \"let the retry read the document and skip what is there\", asks the model to be idempotent, which no model is. The repo's answer is to make the <em>ids</em> idempotent instead: the n-th node id and the n-th op id of a job are functions of the job and the step, the same on every attempt, so a replayed <code>add_node</code> either finds its node already there or is refused by the room as a duplicate op the room already answered.</p>",
  cut("apps/worker/src/ai.ts", "/**\n * The ids a run mints", "/**\n * One AI run: join the document"),
  cut("apps/worker/src/live.ts", "/**\n * An opId that is the same wherever", "\n}\n", include_end=True),
  "<p>Read the op id's input: <code>jobId:op:n:JSON.stringify(op)</code>. The <em>content</em> of the op is in its id, on purpose, and the commit's reasoning is worth keeping whole: with <code>(job, n)</code> alone, a model that does something <em>else</em> at step n on the retry would send a different op under an id the room already journaled, the room would answer with the old op's seq (E6.1's dedupe answers a known <code>(sender, opId)</code> from the journal), the replica would never match that answer to its op, and it would resend for ever. Putting the op's bytes into the hash makes \"a different op at the same step\" a different id: a new op, refused or accepted on its own merits. The id is shaped as a version-8 UUID because the contract says <code>z.uuid()</code> and the room's dedupe key is that string.</p>",
  cut("apps/worker/src/ai.ts", "    const ids = replayIds(job.id);", "    // A run must END"),
  cut("packages/peer-client/src/replica.ts", "export function createReplica({", "{\n"),
  "<p><code>mintOpId</code> was already an injection point: the reconcile simulator (F8a) needs every run of a seed to be identical, so the replica never minted its own ids unconditionally. E9.2a gives it a second caller and passes the op, because the id now depends on it. That is a small lesson in seams: a dependency injected for a test is a dependency you can reuse for a feature, and one you hard-coded is a refactor.</p>",
  cut("apps/worker/src/tools.ts", "  /**\n   * One op, start to finish", "  const tool = <S extends"),
  cut("apps/worker/src/tools.ts", '    tool(\n      "add_node",', '    tool("set_prop"'),
  "<p>The node side. <code>add_node</code> mints the same id at the same step; the replica, holding the document the room sent at welcome, sees that id already exists and refuses with <code>duplicate_node</code> before anything goes on the wire; and the tool asks <code>replayed()</code>: is the node that is there the same component under the same parent? If so, this step is <em>done</em>, the model is told the node id it would have been told, and nothing is sent. If not (the model changed its mind at this step), the refusal stands, the model hears <code>duplicate_node</code>, and its next attempt to add gets a fresh id from the next step. The unit test pins both.</p>",
  cut("apps/worker/src/replay.test.ts", 'test("a retried attempt that replays add_node', 'test("a retry that does something else'),
  cut("apps/worker/src/replay.test.ts", 'test("the op\'s content is in its id', "/** The slice of a peer"),
  "<p><strong>The other two queues.</strong> Ship needs nothing new: a branch that already holds the page gets no commit, and Gitea's 409 on an existing pull request finds the open one (E5.5's idempotence), so a retried ship makes no second PR. Sandbox needs one thing: the stale sweep clears the dead worker's address (the <code>output</code> case in section 2), so the document's preview comes back under the next attempt instead of pointing at a container nobody runs. The chaos check does all three rounds with a real <code>kill -9</code>.</p>",
  cut("scripts/chaos/kill-worker-resumes.ts", "// chaos:kill-worker-resumes (E9.2a", "import { execFileSync }"),
  cut("scripts/chaos/stub-worker.ts", "const scripted: RunAgent", "const never ="),
  cut("scripts/chaos/kill-worker-resumes.ts", '    docker("kill", "--signal", "SIGKILL", first);', "    const room = person(doc);"),
  "<p>Read what the AI round measures. It kills the stub worker container after five journaled steps, asserts that the row still says <code>running, attempts = 1</code> and that <em>nothing moves</em> for two seconds while no worker is alive (a check that the job is not being run by something the script did not start), starts a second stub, and waits. Then: succeeded as attempt 2; the second attempt's <code>started_at</code> at least <code>staleMs</code> after the first's last <code>heartbeat_at</code>, both by Postgres's clock; the journal holds exactly 20 <code>add_node</code> ops with 20 distinct op ids and 20 distinct node ids for this run; seqs 1..20 with no gap; and a fresh peer's document holds exactly 20 Stacks. The stub is the real worker loop, the real AI handler and the real peer with a scripted agent in place of the model, running inside the worker image on the compose network, so the only thing not real is the model, and the model is the one part whose behaviour a retry cannot rely on anyway.</p>",
  vs([("<code>createHash(\"sha256\").update(text).digest(\"hex\")</code> sliced into a UUID shape", "<code>UUID.nameUUIDFromBytes</code> (version 3, MD5): the same idea, a name-based UUID", "<code>uuid.uuid5(namespace, name)</code>"),
      ("a closure over two counters (<code>ops</code>, <code>nodes</code>): state per run, no class", "an object with two <code>int</code> fields", "a closure or a small class"),
      ("<code>replayed = (): boolean =&gt; ...</code> as a default parameter", "an overload with a <code>BooleanSupplier</code>", "a keyword argument with a lambda default"),
      ("<code>mintOpId?: (op: Op) =&gt; string</code>: an optional injected function", "a functional interface passed to the constructor", "an optional callable parameter"),
      ("<code>docker(\"kill\", \"--signal\", \"SIGKILL\", name)</code> from a script", "<code>ProcessBuilder</code>", "<code>subprocess.run</code>"),
      ("<code>psql(...).split(\"|\")</code> with defaults in the destructuring", "JDBC in the harness", "psycopg in the harness")]),
  case("The op id as (job, step) alone was rejected: a resend for ever.",
       "<p>The first design hashed the job id and the step number. The refutation was a scenario, not a test: attempt 2's model adds a Button where attempt 1 added a Stack at step 3; the room finds the op id in its journal and answers with the Stack's seq; the replica has no pending op whose content that answer matches and keeps the Button pending; the ack timeout fires and it resends, and the room answers the same thing again. Adding the op's JSON to the hash costs nothing and makes the case impossible: a different op is a different id.</p>"),
  case("Skipping steps by reading the tree was rejected.",
       "<p>\"Read the document first and do not add what is there\" is an instruction to the model, and a model that follows instructions perfectly is not a model. Worse, it would have made the retry's behaviour depend on the prompt. The ids make the replay safe whatever the model does: the same step is absorbed, a different step is a new op.</p>"),
  case("A different plan on the retry is absorbed only where it repeats itself.",
       "<p>The ponytail is named in the commit: attempt 2 that adds different nodes adds them, and the run then shows what both attempts did. The ceiling is a document with some extra nodes after a crash; the upgrade is to resume the agent from its recorded tool calls, which is what E9.4's progress list is the first step towards.</p>"),
  note("<strong>The principle:</strong> when the producer of a retried action cannot be made deterministic, make its <em>identifiers</em> deterministic and let the consumer deduplicate. Kafka's idempotent producer does it with a sequence number per partition; here the id is a hash of (job, step, content), the replica dedupes nodes and the room dedupes ops. The content belongs in the id whenever \"the same step, a different action\" must be told apart from \"the same action again\"."))

section("redis", "4 · Redis is a cache: the wipe, and why no code changed",
  "<p>E9.2b is the epic's shortest bead and its most instructive: <em>no production code changes</em>. SPEC §4 asks that a Redis lost (flushed or restarted with no persistence) loses no job and no room, and the answer had been built piece by piece since epic 3. What was missing was the proof, and the proof is a chaos script with two rounds and a pure judge. Read the list of what already made it true, because each item is a place where an earlier epic chose Postgres over Redis for the truth.</p>",
  "<p><strong>Jobs.</strong> The worker's sweep (E3.1) re-offers every row Postgres still calls <code>queued</code>, every five seconds in compose; <code>jobId</code> as the BullMQ id plus <code>claim()</code> make a second offer harmless. A <em>running</em> job heartbeats Postgres, not Redis, so the wipe never notices it; BullMQ loses the job's lock and cannot record its end, which it logs, and Postgres records it, which is what counts. <strong>Rooms.</strong> After a wipe the owner's compare-and-renew finds no key and gives the room up at once (4409 to its peers), the next acquire takes the token floor from the journal's fence (E7.3), so the token keeps rising and no second owner can write, and the routing heartbeats come back within a tenth of a ttl. <strong>Roles.</strong> The E8.2 pub/sub subscriber re-reads every role (<code>\"all\"</code>) on reconnect, and a FLUSHALL keeps subscriptions alive anyway.</p>",
  cut("scripts/chaos/redis-wipe-rebuild.ts", "// chaos:redis-wipe-rebuild (E9.2b", "import { execFileSync }"),
  cut("scripts/chaos/redis-wipe-rebuild.ts", "type Wipe =", "const LONG ="),
  "<p>Two ways of losing Redis, because they are different failures. <code>FLUSHALL</code> empties every key while every connection stays open: nobody is told, subscriptions survive, and a client with a stale idea of what it holds finds out only when it asks. A <em>restart</em> drops every connection too, so every client reconnects and BullMQ's blocking pops return with errors. The script checks that the restart really happened (<code>run_id</code> changed) so a round cannot pass by doing nothing.</p>",
  cut("scripts/chaos/rebuild.ts", "// What chaos:redis-wipe-rebuild (E9.2b", "export function leaseViolations"),
  cut("scripts/chaos/rebuild.ts", "export function leaseViolations"),
  "<p>The judge is a pure function over what the script read from Postgres and Redis afterwards, and it has a unit test of its own (<code>rebuild.test.ts</code>, mutation-checked on the <code>attempts</code> and fence guards): every run <code>succeeded</code> with <code>attempts = 1</code>, because a wipe must <em>not</em> start a job twice (that is section 2's job, and a wipe is not a dead worker); every step journaled once with distinct op ids and node ids; seqs with no gap; a lease back under a <em>larger</em> token; and <code>documents.fence_token</code> naming exactly that token, which is the one-owner property from lesson 7. The two vacuity guards are SPEC §4a's rule: a round in which nothing was waiting in Redis, or nothing running, proved nothing, and says so instead of passing.</p>",
  cut("apps/worker/src/crash.int.test.ts", 'test("Redis wiped under a working worker'),
  "<p>The integration version wipes only its own prefix (the test Redis is shared), with one Lua script so the wipe is atomic as <code>FLUSHALL</code> is: nothing can land between listing the keys and deleting them. It then releases the running handler and asserts every job succeeded, each handler was called once, <code>attempts = 1</code>.</p>",
  vs([("What a wipe loses", "the <code>wait</code> lists, the locks, the lease keys, the routing heartbeats, the pub/sub state (on restart)", "", ""),
      ("What brings jobs back", "the sweep: <code>select ... where status = 'queued'</code> every 5 s, offered again; <code>claim()</code> refuses a duplicate", "Celery with a Redis broker: the messages are gone and the tasks never run unless you kept your own table", "Sidekiq: jobs in Redis are the truth, so a flush is data loss; Sidekiq Pro's reliable fetch survives a crash, not a flush"),
      ("What brings rooms back", "the owner's renew finds no key and closes with 4409; the next acquire's floor is the journal's fence", "ZooKeeper and etcd persist their state (Raft log), so a restart is not a wipe; a Redisson lock on a flushed Redis is simply gone and the holder does not know", ""),
      ("What a running job feels", "nothing: its heartbeat and its finish are Postgres rows", "Spring Batch's repository is JDBC: the same property", "Celery's result backend on Redis: the result is gone"),
      ("The upgrade never taken", "a sentinel key to detect a flush and rebuild at once", "", "rejected: the sweep is 5 s and a marker is a moving part for no visible gain")], head=("Question", "This repo", "Java world", "Python world")),
  case("Detecting the flush with a sentinel key was rejected.",
       "<p>A key written at boot and checked on every sweep would say \"Redis was wiped\" and let the worker rebuild at once instead of within one sweep. The sweep already runs every five seconds and already does the rebuild; the sentinel adds a write, a read and a branch for a gain nobody can see. The same reasoning killed a \"queue depth\" gauge in E3: measure what the row says.</p>"),
  case("The vacuity guards exist because a first draft passed with nothing waiting.",
       "<p>The script's runs were too short: by the time the wipe landed, every run had been claimed and none was in Redis's <code>wait</code> list, so \"the waiting runs were offered again\" was true of an empty set. §4a's rule is that a chaos check must prove the failure was <em>present</em>; the script now reads <code>LLEN bull:ai:wait</code> before the wipe and the judge refuses a round that saw zero.</p>"),
  note("<strong>The principle, in the words the epic keeps using:</strong> the row is the truth and the message is a pointer to it. A pointer can be lost and re-derived from the truth (the sweep); the truth cannot be re-derived from the pointer. Every place an earlier epic was tempted to keep state only in Redis (the lease's token, the job's lock, the presence) was made re-derivable or was made a hint, and E9.2b is the receipt."))

section("progress", "5 · Progress through the row: steps that survive a reload and never show a dead attempt's work",
  "<p>A person who asked the AI for a page sees the nodes appear on the canvas, but not what the AI is <em>doing</em>: which tool it called, whether a call was refused, how far it is. F30 asks for a list of steps that streams while the run goes and survives a reload. The transport question came first and was answered with the one already there: the panel polls the run once a second (E3.2's status poll), so the steps ride the same request and reach the browser through the same <code>/api</code> path the ngrok host proxies. No SSE (a new long-lived connection through Vite's proxy and ngrok for a few events a second), no sync socket (the room is the document's channel, and a run's bookkeeping in it would be journaled, fenced and replayed with the ops).</p>",
  cut("packages/contracts/src/index.ts", "/**\n * F30: one tool call of a run", "export const Run = z.object({"),
  "<p><code>detail</code> is the model's own argument: a component name, a prop key, a node id. It is <em>untrusted text</em> in every sense the earlier lessons gave that phrase: the contract caps it at 80 characters, the worker strips every <code>\\p{C}</code> character (control characters and, in particular, bidi overrides that could make a line read backwards on screen), the row parser reads it back through the same contract, and the panel renders it as a text node. <code>tool</code> reuses <code>FailureReason</code>'s shape, a lower-case name, because that is what a tool name is and it keeps the enum open for a worker newer than the browser.</p>",
  cut("apps/worker/src/progress.ts", "import { MAX_RUN_STEPS"),
  cut("apps/worker/src/ai.ts", "    // One write at a time, in order", "    try {\n      const live"),
  cut("apps/worker/src/ai.ts", "    } finally {\n      clearInterval(watchdog);", "// before the worker finishes the row: a step written after that would land nowhere (report needs `running`)", include_end=True),
  "<p>Three decisions in the worker. <strong>The whole list, every time</strong>: <code>onSteps</code> gets the last fifty steps after each call, so a write that failed is made good by the next one and no step is ever lost to one dropped query. <strong>One write at a time, in order</strong>: <code>reporting = reporting.then(...)</code> chains the writes, so a later list never lands before an earlier one, and a list written at step 7 cannot be overwritten by the list of step 6 arriving late. <strong>Awaited before the row is finished</strong>: <code>report</code> needs <code>status = 'running'</code> (section 2's rule that a finished job is not written to), so the handler's <code>finally</code> waits for the chain before returning to the worker, which will call <code>finish</code>.</p>",
  cut("packages/db/src/index.ts", "      async report({ queue, jobId, orgId, attempt }, output) {", "      sandboxesInUse:"),
  "<p><code>report</code> is fenced by the attempt like every other write, and here the fence has a visible consequence: a slow dead attempt's steps <em>land nowhere</em>, so the panel never lists a tool call nobody is making. And <code>requeueStale</code> clears an AI job's <code>output</code> when it requeues it, so the retry's list starts empty rather than showing the dead attempt's steps as if they were its own. The integration test does both: reports from attempt 1, requeues, asserts an empty list, claims attempt 2, reports from attempt 1 again (the slow worker waking up), asserts still empty, reports from attempt 2, asserts that list.</p>",
  cut("packages/db/src/run-progress.int.test.ts", 'test("a dead attempt\'s steps never show', 'test("steps are checked against the contract'),
  cut("packages/db/src/index.ts", "// A run's progress is written by our own worker but quotes the model", "// bigint and numeric arrive as STRINGS"),
  "<p><code>RunRow</code> parses <code>output</code> with <code>RunProgress.safeParse</code> and shows <em>no steps</em> for a row that does not parse, rather than throwing. The row was written by our own worker through the same contract, so a failure here means someone edited the column by hand or a newer worker wrote a shape this build does not know; either way the run must still be readable, and its steps are the part to drop. The test writes <code>{\"tool\": \"&lt;b&gt;\", \"ok\": 1}</code> straight into the column and asks for an empty list.</p>",
  cut("apps/api/src/app.ts", "  // F30: the newest run, with its steps so far.", "  // F15: the document's running page."),
  cut("apps/web/src/AiPanel.tsx", "  // The newest run, after a reload too (F30).", "  const start = (): void => {"),
  "<p>The reload. <code>GET /documents/:id/run</code> answers the document's newest run (as <code>GET /ship</code> does), viewer role, 404 when the document is not the caller's, <code>null</code> when the AI was never asked. The panel reads it on mount; <code>setRun((current) =&gt; current ?? latest)</code> is the guard the comment names: a run the person started in the half-second before the answer arrived must not be replaced by an older one, and a functional <code>setState</code> is how React lets you decide against the value that is current <em>now</em> rather than the one captured when the effect started (lesson 2's external-store idiom, in one line). Steps stay on the row after the run ends, so a reload afterwards still says what the run did.</p>",
  cut("apps/web/src/progress.ts", "import type { RunStep }"),
  cut("e2e/progress.spec.ts", "  await page.reload();", '  await expect(page.locator("#ai-status")).toHaveAttribute("data-run-status", "succeeded", { timeout: 15_000 });'),
  vs([("<code>raw.replace(/\\p{C}/gu, \"\").slice(0, 80)</code>: Unicode property escapes", "<code>s.replaceAll(\"\\\\p{C}\", \"\")</code>", "<code>\"\".join(c for c in s if unicodedata.category(c)[0] != \"C\")</code>"),
      ("<code>reporting = reporting.then(() =&gt; ...).catch(() =&gt; undefined)</code>: a promise chain as a serial queue", "a single-thread <code>Executor</code>", "an <code>asyncio.Queue</code> with one consumer"),
      ("<code>setRun((current) =&gt; current ?? latest)</code>: a functional state update", "no analogue; a compare-and-set on an <code>AtomicReference</code> is the nearest", "no analogue"),
      ("<code>RunProgress.safeParse(r.output)</code> and <code>steps: []</code> on failure", "a <code>try</code> around Jackson's <code>readValue</code>", "<code>pydantic.ValidationError</code> caught and an empty list"),
      ("<code>Object.hasOwn(args, key)</code> before reading a model's argument", "<code>map.containsKey</code>", "<code>key in args</code>"),
      ("<code>{run.steps.map((step, at) =&gt; &lt;li key={at}&gt;{stepText(step)}&lt;/li&gt;)}</code>: text nodes only", "Thymeleaf's <code>th:text</code> escapes; <code>th:utext</code> would not", "Django templates autoescape; <code>|safe</code> would not")]),
  case("SSE and the sync socket were rejected as the transport.",
       "<p>Server-sent events would stream each step at once, and they would add a long-lived connection through two proxies (Vite's and ngrok's) for something that arrives a few times a second at most. The sync socket already exists and is the wrong channel: everything on it is an op or presence, journaled, fenced by the lease, replayed on reconnect; a run's steps are none of those things. The 1 s poll already existed for the status and now carries the steps; a step shows up to a second late, which the ponytail names.</p>"),
  case("The list is reported whole, not appended.",
       "<p>Appending one step per write is the obvious shape, and it makes every dropped write a hole in the list and every reordered pair a list out of order. Sending the last fifty every time makes a write idempotent (the same list twice is the same list) and self-healing (the next write carries what the last one lost), at the cost of a few kilobytes per tool call, which a run makes a few times a second at most.</p>"),
  note("<strong>The principle:</strong> a progress view is derived state, so put it where the state is and let the readers you already have read it. The row already had a poller and already had a fence; the steps inherit both, and the one new route exists for the one new question, \"which run should a fresh page follow\"."))

section("limits", "6 · Rate limits in Postgres: one upsert, inside the transaction, with the database's clock",
  "<p>An org that starts too many AI runs costs money and holds worker slots; F31 asks for a per-org limit with a 429 that says <em>exactly</em> how long to wait. The first design question is where to count, and the answer decides everything else. A counter in each api process lets N instances allow N times the limit. Redis <code>INCR</code> with <code>EXPIRE</code> is shared, and it was rejected for two reasons the commit names: it is a second store that can fail on its own, so the code must pick between failing open and failing closed when Redis is away; and it cannot join the run's transaction, so a run that was refused as busy, or rolled back, or replayed, would have been charged, and the code would need a compensating decrement. Counting in Postgres, in the same transaction as the run, makes the count exactly the runs that exist.</p>",
  cut("packages/db/migrations/0020_rate_limits.sql", "-- E9.5 (F31)"),
  cut("packages/db/src/limit.ts", "import { z }"),
  "<p>A <em>fixed window</em>: time is cut into windows of <code>windowSeconds</code>, numbered since the epoch, and a key may be hit <code>limit</code> times per window. <code>verdict</code> is pure and takes the database's clock as <code>now</code>, so two api instances whose clocks disagree still give one answer, and the wait is until the window ends, rounded <em>up</em> and never under one second: a client that waits exactly what it is told must be let in, and a \"retry in 0 seconds\" is a lie. The unit test pins the rounding at the boundary.</p>",
  cut("packages/db/src/index.ts", "  /**\n   * One hit on a rate limit (limit.ts).", "  /** One statement, returning ids, holding the org's preview lock"),
  "<p>One upsert. <code>insert ... on conflict (key) do update</code> is atomic per row: two hits at the same moment take turns on the row lock, and each sees the other's count. Read the <code>greatest(r.win, excluded.win)</code>: a hit that computed its window just before the boundary (<code>floor(epoch / windowSeconds)</code> is evaluated when the statement starts) but reached the row after a hit computed just past it must not move the row <em>back</em> a window and reset its count to 1, which would hand out a fresh limit. The <code>case</code> counts it into the newer window instead. <code>clock_timestamp()</code> rather than <code>now()</code>, because <code>now()</code> is the transaction's start time and this hit may be several statements into one.</p>",
  "<p><strong>Inside the transaction.</strong> Section 1's <code>createRun</code> cut shows the order: <code>take</code> first, then <code>insertRun</code>, in one transaction that commits only if a run was made. So a busy document (409), a vanished one (404), a refused run and, through <code>withKey</code>, a replayed key all cost nothing; and a request refused over the limit rolls back its idempotency claim too, so the retry after <code>Retry-After</code> may use the same key, which the integration test asserts by sleeping exactly what the header said. The hit holds the org's counter row until the insert is done, so an org's run starts take turns for the length of one insert, which is the price of exactness and a small one.</p>",
  cut("apps/api/src/app.ts", "/** F31: over a rate limit.", "  return c.json({ error, retryAfterSeconds } satisfies ErrorBody, 429);\n};", include_end=True),
  cut("packages/contracts/src/index.ts", "  /** With 429 rate_limited and too_many_attempts (F31)", "  retryAfterSeconds: z.number().int().min(1).optional(),", include_end=True),
  cut("apps/api/src/config.ts", "/** F31: the default AI run limit, per org.", "export type HttpLimits"),
  "<p><strong>Failure mode, deliberately closed.</strong> The count lives where the run lives: with Postgres away no run can be made either, so the limit cannot fail open, and there is no second store whose absence would need a policy. That sentence is the one to say in an interview when someone proposes Redis for the counter: ask what the code does when Redis is away, and whether \"allow everything\" or \"refuse everything\" is the answer they want under load.</p>",
  cut("packages/db/src/limit.test.ts", 'test("up to the limit goes ahead', 'test("never less than one second'),
  cut("apps/api/src/rate-limit.int.test.ts", 'test("ten starts at once across two api instances', 'test("only runs that are made count'),
  cut("apps/api/src/rate-limit.int.test.ts", 'test("only runs that are made count', 'test("a refused request\'s key is not used up'),
  cut("packages/db/src/usage.int.test.ts", 'test("take: twenty hits at once on one key'),
  "<p><strong>Fixed, sliding, or a bucket.</strong> The ponytail is named in <code>limit.ts</code>: a key may spend its limit at the end of one window and again at the start of the next, twice the rate for a moment. The table is the comparison an interviewer wants, with the honest reason this repo chose the simplest.</p>",
  vs([("Fixed window (this repo)", "one row per key: window index and count; one upsert", "up to 2× the limit across a boundary; the wait is exact and cheap to compute", "sixty runs an hour, and a burst of 120 across the hour mark is a nuisance, not a cost worth a second counter"),
      ("Sliding window (two counters, weighted)", "the current and previous window's counts; the previous weighted by how far into the current window we are", "no boundary burst; approximate (assumes an even spread in the previous window)", "the named upgrade: one more column, the same upsert"),
      ("Sliding log", "every hit's timestamp; count those within the last window", "exact; O(hits) storage and a delete per hit", "a table per key would grow with the traffic it limits"),
      ("Token bucket", "a level and a last-refill time; hits take a token, tokens refill at a rate", "allows bursts up to the bucket size, then a steady rate; the classic API shape (AWS, Stripe)", "the right choice for \"600 requests a minute but bursts are fine\"; two columns and a little arithmetic in the upsert"),
      ("Leaky bucket", "a queue drained at a fixed rate", "smooths bursts into a steady stream; adds latency rather than refusing", "a queue, not a limiter: the jobs table already is one")], head=("Algorithm", "State", "Behaviour", "Here")),
  cut("packages/db/src/index.ts", "        usage: async (input) => {", "        audit: async (input) =>"),
  "<p><strong>Usage, the other half of F31.</strong> The owner reads tokens and estimated cost per run, per person and per day, and the E3.4 review's finding is honoured in the first line: all four reads happen in one <code>REPEATABLE READ</code>, read-only transaction, so a run recorded between two of them cannot show in the totals and not in the items. The user's email is joined as it is <em>now</em>, and a deleted user's runs keep their cost and name no one. The web view is tables of text, with a caption and row and column headers, and the AI panel turns a 429 into a sentence with <code>waitWords</code>, rounded up for the same reason the verdict is.</p>",
  cut("apps/web/src/usage.ts", "/** How long to wait, in words"),
  cut("apps/web/src/api.ts", "/** F31: \"not now\": over a rate limit.", "/** POSTs (or PUTs) and checks the ANSWER"),
  vs([("<code>insert ... on conflict (key) do update set hits = case ... end</code>: an upsert with arithmetic", "the same SQL; <code>MERGE</code> on other databases", "the same SQL"),
      ("<code>extract(epoch from clock_timestamp())</code>: the database's clock, per statement", "<code>CURRENT_TIMESTAMP</code> is the transaction's; use the same function", "the same"),
      ("<code>Math.ceil((window + 1) * windowSeconds - now)</code>", "<code>Math.ceil</code> on <code>double</code>s", "<code>math.ceil</code>"),
      ("<code>z.strictObject({ limit, windowSeconds })</code> with <code>.max(86_400)</code>", "a record with Bean Validation <code>@Max</code>", "a pydantic model with <code>le=86400</code>"),
      ("<code>via: Pool | PoolClient = pool</code>: the same query inside or outside a transaction", "a method taking a <code>Connection</code>, with an overload that borrows one", "a function taking a cursor"),
      ("<code>c.header(\"retry-after\", String(seconds))</code>", "<code>ResponseEntity.status(429).header(\"Retry-After\", ...)</code>", "<code>HttpResponse(status=429, headers={\"Retry-After\": ...})</code>"),
      ("<code>begin transaction isolation level repeatable read read only</code>", "<code>@Transactional(isolation = REPEATABLE_READ, readOnly = true)</code>", "<code>connection.set_session(isolation_level=..., readonly=True)</code>")]),
  case("Redis INCR + EXPIRE was rejected.",
       "<p>It is the textbook shared counter and it fails the two questions this design asks. When Redis is away, what does the code do: open (every org unlimited under exactly the load that took Redis down) or closed (no runs, with Postgres healthy)? And when a run is refused, rolled back or replayed, how is the count corrected: a <code>DECR</code> that itself can fail? Counting in the run's transaction has no second failure and no compensation.</p>"),
  case("The greatest(win) clause exists because of a hit that crossed the boundary in flight.",
       "<p>The first upsert wrote <code>win = excluded.win</code> and reset the count when the windows differed. Two hits at 3599.99 s and 3600.01 s into an hour could land in the other order (the first is evaluated, waits on the row lock, and reaches it after the second): the row moved back to the old window with <code>hits = 1</code>, and the next hit in the new window saw <code>r.win &lt; excluded.win</code> and reset again. <code>greatest</code> and the <code>&gt;=</code> in the <code>case</code> make the row's window monotonic.</p>"),
  case("A single limit for every org is the ponytail; a column is the upgrade.",
       "<p><code>AI_RUNS_PER_HOUR</code> is one number for the deployment. The moment plans differ, the rule comes from a column on <code>orgs</code> read in the same transaction; nothing in <code>take</code> changes. Fixed windows are the other named ceiling: a burst across the hour mark is twice the limit for a moment, which for sixty runs an hour is not a cost worth a second counter.</p>"),
  note("<strong>The principle:</strong> count where the counted thing is written, in the same transaction, and take the clock from the same place. Then \"the count is exactly the runs that exist\" is a fact rather than a reconciliation, the limit cannot fail open because there is no second store to lose, and the wait you tell the client is the truth to the second."))

section("http", "7 · Every route limited, and who is asking: per user, per address, and the header you may not believe",
  "<p>E9.6 spreads section 6's upsert over every HTTP route, and the question becomes <em>which key</em>. A caller the api recognises is charged per user, whatever address they come from: an editor's open canvas polls about three times a second, so 600 a minute. A public route (sign-up, sign-in, sign-out, <code>/auth/me</code>) names no user, and a request whose cookie is bad or missing is nobody, so both are charged per client address: 300 a minute, and that is what turns a 401 into a 429 for someone guessing session tokens. Minting a sync session has a tighter count of its own, and sign-in a count per email that E8.1 left a seam for.</p>",
  cut("apps/api/src/app.ts", "  // E9.6 (F31): and every route is rate limited but the probes", "    await next();\n  });", include_end=True),
  "<p>Read the order inside <code>requireUser</code>. The probes are never counted: an orchestrator that is refused a health check kills a healthy process, and a rate limit that can take the api down is a self-inflicted outage. The webhook is never counted: the HMAC is its gate, and a refused delivery would only fall back to the reconcile. For everyone else the count is taken <em>before</em> the 401 is answered, so an unauthenticated flood costs the flooder, and the answer over the limit is 429 whether or not they had a cookie: refusing first tells a guesser nothing about which of their guesses were closer.</p>",
  cut("apps/api/src/config.ts", "/** F31: the default AI run limit, per org.", "export type HttpLimits"),
  cut("apps/api/src/app.ts", "  // E9.6: minting a sync session has its own, tighter limit per user", "  const document = new Hono"),
  "<p>The mint limit is taken <em>before the document is looked up</em>, and the reason is lesson 8's revoked collaborator: their peer's <code>/session</code> gets a 404 and gives up, but a client that keeps asking regardless (a bug, a script) would cost a membership read per request for a person who has no business with the document. Charging first makes the refusal cheap, and the tighter count (60 a minute against 600) means the guest is refused with requests to spare on their general count while the owner's mints are untouched.</p>",
  cut("apps/api/src/app.ts", "  const attempt = allowAttempt ??", "  // Paid for now"),
  cut("apps/api/src/app.ts", "  // No such email and the wrong password are one answer", 'fail(c, 401, "invalid_credentials");\n  });', include_end=True),
  "<p>The seam E8.1 left, <code>allowAttempt</code>, now defaults to the limiter: 10 tries per 5 minutes per route and email, so an online guesser gets ten attempts at one account whatever address they come from, and the answer is <code>too_many_attempts</code> <em>with</em> a Retry-After now. The key is hashed because an email can be longer than the <code>rate_limits</code> key allows and because the table need not hold addresses; SHA-256 keeps the key short and the email out of the row. This is the fourth layer of lesson 8's sign-in: slow hash, constant-time compare, dummy hash, and now a count.</p>",
  cut("apps/api/src/client-address.ts", "/**\n * E9.6 (F31): who is asking", "const NAMED"),
  "<p><strong>The header you may not believe.</strong> <code>X-Forwarded-For</code> is a comma-separated list, and the rule is that each proxy <em>appends</em> the address it saw the request come from. So the rightmost entry was written by the last proxy, the one before it by the proxy before, and the leftmost by whoever started the chain, which may be the client, who may write anything. The classic bug reads the <em>leftmost</em> entry as the client (\"the original IP\"): every guesser then picks a fresh address per request and the per-address limit counts nothing. The correct read is from the <em>right</em>: skip every entry that is itself a proxy you trust, and the first entry that is not is the client, vouched for by a trusted hop. And the whole header is believed only when the TCP peer itself is a trusted proxy; from anyone else it is ignored, because anyone can send one.</p>",
  cut("apps/api/src/client-address.ts", "/** `spec`: comma-separated", "/** The client's address (see above)"),
  cut("apps/api/src/client-address.ts", "/** The client's address (see above)"),
  "<p>Two more decisions in the code. <code>unmap</code> turns <code>::ffff:127.0.0.1</code>, an IPv4 client on a dual-stack socket, into <code>127.0.0.1</code>, so one client is one key and the loopback check works whichever family the socket reported. And a garbled entry (<code>1.2.3.4:80</code>, a word) stops the walk and charges the last address a trusted hop vouched for: a client who sends nonsense costs themselves, never someone else. <code>trustedProxies</code> refuses a spec it does not understand rather than trusting nobody or everybody: a typo in <code>TRUST_PROXY</code> must not start the api.</p>",
  cut("apps/api/src/config.ts", "  // E9.6: the peers whose X-Forwarded-For names the client", "});\n\nexport type SessionConfig"),
  cut("docker-compose.yml", "      # The host's Vite proxy (and the ngrok agent behind it)", '    ports: ["127.0.0.1:${API_PORT:-3000}:3000"]'),
  "<p>Why <code>loopback,private</code> in compose and <code>loopback</code> on the host: the api on the host sees Vite (and the ngrok agent behind it) on 127.0.0.1; the api in a container sees the host's Vite through Docker's gateway, a private address. Trusting private addresses is safe there because the port is published on <code>127.0.0.1</code> only and the sandboxes live on their own network, so a private peer can only be the host or one of our own containers. The same string on a server with a public interface would be wrong, and the comment says so.</p>",
  cut("apps/api/src/client-address.test.ts", 'test("behind a trusted proxy the client is the rightmost', 'test("no header, a garbled one'),
  cut("apps/api/src/http-limits.test.ts", 'test("minting a session has its own tighter limit', 'test("sign-in attempts default to the limiter'),
  cut("apps/api/src/http-rate-limit.int.test.ts", 'test("public routes are counted per client address', 'test("an untrusted peer'),
  cut("apps/api/src/http-rate-limit.int.test.ts", 'test("an untrusted peer\'s X-Forwarded-For is ignored', 'test("sign-in is limited per email'),
  cut("apps/api/src/http-rate-limit.int.test.ts", 'describe("integration:session-mint-limit"'),
  vs([("<code>new BlockList()</code> with <code>addSubnet</code> and <code>check</code>: CIDR matching from <code>node:net</code>", "<code>IpAddressMatcher</code> from Spring Security", "<code>ipaddress.ip_network(...)</code> and <code>in</code>"),
      ("<code>isIP(address)</code>: 0, 4 or 6", "<code>InetAddress.getByName</code> (which may resolve a name: do not)", "<code>ipaddress.ip_address</code> raising"),
      ("the walk from <code>hops.length - 1</code> down", "Tomcat's <code>RemoteIpValve</code> does the same walk with <code>internalProxies</code>", "gunicorn's <code>forwarded_allow_ips</code> gates the header; the walk is yours"),
      ("<code>Record&lt;string, readonly (readonly [string, number])[]&gt;</code>: named sets of subnets", "a <code>Map&lt;String, List&lt;Subnet&gt;&gt;</code>", "a dict of lists of tuples"),
      ("<code>z.string().optional().transform((value, ctx) =&gt; { ... ctx.addIssue(...); return z.NEVER })</code>: a parse that can refuse", "a <code>@ConfigurationProperties</code> validator", "a pydantic <code>field_validator</code> raising"),
      ("<code>hono.request(path, init, { incoming: { socket: { remoteAddress } } })</code>: a peer address for an in-process request", "<code>MockHttpServletRequest.setRemoteAddr</code>", "Django's <code>RequestFactory(REMOTE_ADDR=...)</code>")]),
  case("Believing X-Forwarded-For from anyone was rejected, and so was the leftmost entry.",
       "<p>Both are the default in more frameworks than one would like. With either, a per-address limit is a per-<em>claimed</em>-address limit, and a guesser with a for loop has infinite addresses. The integration test sends four requests over a real socket with four different headers to an api that trusts nobody and asks for <code>[200, 200, 200, 429]</code>: the header changed and the count did not.</p>"),
  case("Postgres for a per-request write, with its ceiling named.",
       "<p>One upsert per request and a hot row per user is a real cost: a few thousand requests a second on one primary is the ceiling the commit names. It was accepted because the count must be shared across instances either way, <code>Db.take</code> exists and is proven, every counted route already reads Postgres for identity, and the failure mode is closed for free. The upgrade, Redis <code>INCR</code> failing open, is one function behind the same seam.</p>"),
  case("The probes exempted after asking what an orchestrator does with a 429.",
       "<p>A liveness probe that is refused is a container that is restarted; a readiness probe that is refused is a pod taken out of the load balancer. A limit that can do either under load makes the outage it was meant to prevent. The webhook is exempt for a different reason: its gate is the HMAC, and a limited delivery only delays the reconcile.</p>"),
  note("<strong>The principle:</strong> a rate limit is only as good as the identity it counts. Count the user when you know one; when you do not, count an address you can actually attribute, which means the TCP peer or an <code>X-Forwarded-For</code> entry a proxy you configured has vouched for, read from the right. And exempt the two callers whose refusal would hurt you more than their traffic: the probes and the signed webhook."))

section("tradeoffs", "8 · Trade-offs and comparisons: where this design sits",
  "<p>The questions an interviewer asks about job hardening, with the honest answers for this one.</p>",
  vs([("Duplicate presses", "an <code>Idempotency-Key</code> claimed by a primary key in the job's transaction; a replay reads the job's row; 422 on a different request; 24 h", "Stripe's contract, hand-built: Spring has no built-in; Spring Integration's <code>IdempotentReceiver</code> dedupes messages, not HTTP", "Django: hand-built, or <code>django-idempotency-key</code> (cache-backed, so not transactional)"),
      ("A dead worker", "a 1 s heartbeat on the row, a 15 s sweep in one <code>skip locked</code> statement, 3 attempts, <code>worker_lost</code>", "Spring Batch: restartable steps from the <code>JobRepository</code>, by hand; Quartz misfires; Kafka consumers: a rebalance re-delivers the partition", "Celery: <code>acks_late</code> and a visibility timeout; the task runs again and may run twice"),
      ("A slow worker mistaken for dead", "the attempt fences <code>finish</code>, <code>heartbeat</code> and <code>report</code>; the slow one learns <code>lost</code> and aborts", "optimistic locking with <code>@Version</code> is the same fence if you remember to use it", "the same, by hand"),
      ("A replayed step", "ids as hashes of (job, step, op); the replica dedupes nodes, the room dedupes ops", "Kafka's idempotent producer (sequence per partition); exactly-once semantics with transactions", "the task is asked to be idempotent"),
      ("Redis lost", "nothing to do: the sweep rebuilds the queue from Postgres, the lease floor comes from the journal; proven by a chaos script", "Sidekiq/Resque on Redis: the queue is the truth and a flush is loss; RabbitMQ with durable queues survives a restart, not a purge", "Celery with Redis: the same loss; with RabbitMQ durable queues, a restart"),
      ("Progress", "the steps on the row, the last 50, fenced by the attempt; the 1 s status poll carries them; a reload asks for the newest run", "Spring Batch's <code>StepExecution</code> counts; a UI polls", "Celery's <code>update_state(meta=...)</code> to the result backend: the same idea, in Redis"),
      ("Per-tenant limits", "a fixed window in Postgres, in the run's transaction; <code>Retry-After</code> from the database's clock; cannot fail open", "Bucket4j with a JDBC or Redis backend; resilience4j per instance", "django-ratelimit (cache), or a Redis <code>INCR</code>"),
      ("Per-request limits", "the same upsert per user, per address, per mint, per email; probes and webhook exempt", "Spring Cloud Gateway's <code>RequestRateLimiter</code> (Redis, token bucket); nginx <code>limit_req</code> in front", "nginx <code>limit_req</code>; django-ratelimit per view"),
      ("Client address", "the rightmost <code>X-Forwarded-For</code> entry past a trusted proxy; a typo in <code>TRUST_PROXY</code> refuses to start", "<code>RemoteIpValve</code> / <code>ForwardedHeaderFilter</code> with trusted proxies configured", "gunicorn <code>forwarded_allow_ips</code>; django-ipware with <code>proxy_count</code>")], head=("Question", "This repo", "Java world", "Python world")),
  "<p><strong>What is deliberately simple.</strong> Fixed windows and constants for the limits (an env var for the AI limit, a table of four rules for HTTP), one limit for every org, IPv6 addresses keyed whole, <code>rate_limits</code> rows never pruned (one per user, address and email), idempotency keys swept only when their user next sends one, a step that may show a second late, fifty steps kept, a replay that enqueues again, a retried AI attempt whose different plan adds different nodes. Every one is named where it lives, with its ceiling and its upgrade.</p>",
  "<p><strong>What is not solved.</strong> A <code>git_events</code> row left <code>running</code> by a killed git peer stays there: resetting it is easy, but replaying a half-applied push would refuse it whole as <code>reused_node_id</code>, so push-ops must become replay-safe first. A retried ship that finds nothing new to commit overwrites its output with <code>commit: null</code>, and if the git peer had not yet handled the first attempt's push, that push would be diffed. Usage for runs that fail or exhaust their budget, and per-turn token accounting, are the E3.4 review's items 1 and 2 and were outside this epic's paths. The sync side's byte and fan-out budgets are the bead's deferred notes.</p>",
  note("<strong>The interview answer in one breath:</strong> an idempotency key claimed by a primary key inside the job's own transaction, so twenty simultaneous retries block on one row and answer from the job as it now is; a heartbeat on the row, a stale sweep in one <code>skip locked</code> statement, and the attempt number in every write as the fence that makes a false \"dead\" harmless; ids that are hashes of job, step and content so a replay is deduplicated by the replica and the room; Redis as a cache whose loss the sweep and the fence floor repair, proven by a chaos script with vacuity guards; progress as a fenced column read by the poll that already existed; and rate limits as one upsert in Postgres, inside the run's transaction for AI runs and per request for everything else, keyed by the user or by an address a trusted proxy vouched for, with the wait computed from the database's clock and no way to fail open."))

section("testing", "9 · Testing a crash you cannot schedule, a race you can, and a limit to the second",
  "<p>The split from the earlier lessons holds: every decision has a pure test that ran on every commit; every I/O rule has an integration or chaos check that is written and unrun. Six shapes are new to this epic.</p>",
  "<p><strong>Twenty at once.</strong> <code>Promise.all</code> over twenty <code>fetch</code>es is the whole concurrency harness for the idempotency and the rate-limit tests. It works because the claim is serialised by the database, not by the test: the assertion is on rows (<code>select id, status from jobs</code>) and on the set of ids in the answers, never on timing. Two api instances over one database (<code>buildApp</code> twice) prove the count is shared.</p>",
  "<p><strong>The dead worker, simulated by moving a timestamp.</strong> <code>kill -9</code> cannot be scheduled inside a vitest process, but what it leaves can: a row with <code>status = 'running'</code> and a <code>heartbeat_at</code> in the past. <code>silentFor(jobId, 60)</code> is one <code>UPDATE</code>, and the whole sweep can then be asserted in milliseconds. The slow-worker case is the same trick the other way: bump <code>attempts</code> and the beat by hand, as the sweep and another claim would, while the first worker's handler is still open, and watch its finish land nowhere.</p>",
  cut("apps/worker/src/crash.int.test.ts", "    // The wipe: every key of this file's prefix", "    release();"),
  "<p><strong>An atomic wipe of one prefix.</strong> The test Redis is shared, so <code>FLUSHALL</code> would break the other suites; a <code>KEYS</code> then a loop of <code>DEL</code>s from the client would let a key land in between. One Lua script does both in Redis's single thread, which is exactly how <code>FLUSHALL</code> is atomic, and <code>defineCommand</code> is ioredis's way to add one.</p>",
  cut("apps/api/src/rate-limit.int.test.ts", "/** Seconds to the end of the current window by the DATABASE's clock", "const sleep"),
  "<p><strong>The wait, to the second, by the right clock.</strong> A test that computed the expected <code>Retry-After</code> from <code>Date.now()</code> would be comparing two clocks; <code>secondsLeft</code> asks Postgres, the clock the limiter reads, and allows two seconds for the round trip and the rounding. The key-not-used-up test then <em>sleeps exactly what the header said</em> and expects 201: the assertion is that the promise the header makes is kept.</p>",
  cut("apps/api/src/http-limits.test.ts", "function app({ trust", "const ann ="),
  "<p><strong>The wiring against an in-memory limiter.</strong> Which key each request is charged to, and which requests are charged at all, is a question about the middleware, not about Postgres; <code>http-limits.test</code> gives <code>buildApp</code> a <code>take</code> that records keys and counts in a <code>Map</code>, and asserts the exact list of keys per request sequence. Hono's third argument to <code>request</code> plants a peer address, so the client-address rules run in-process. The commit records the mutation check: dropping the probe exemption or the mint charge turns the test red.</p>",
  cut("scripts/chaos/rebuild.test.ts", 'describe("runViolations"', 'describe("leaseViolations"'),
  "<p><strong>The chaos judge as a pure function.</strong> A chaos script is a long, slow, Docker-bound thing; its <em>verdict</em> need not be. <code>rebuild.ts</code> takes what the script read afterwards and returns a list of violations, and <code>rebuild.test.ts</code> feeds it a claimed-twice run, a seq gap, a missing run and an empty wipe, and asks for the exact sentences. That is where the vacuity guards were mutation-checked, without running Docker once.</p>",
  vs([("<code>Promise.all(Array.from({ length: 20 }, () => fetch(...)))</code>", "<code>CompletableFuture.allOf</code>", "<code>asyncio.gather</code>"),
      ("<code>update jobs set heartbeat_at = now() - make_interval(secs =&gt; $2)</code>: the past, as a fixture", "the same SQL from the test", "the same"),
      ("<code>redis.defineCommand(\"wipe\", { numberOfKeys: 0, lua })</code>", "Jedis <code>eval</code>; Lettuce <code>eval</code>", "<code>redis.register_script</code>"),
      ("<code>expect(Math.abs(retry - left)).toBeLessThanOrEqual(2)</code>: a tolerance, stated", "<code>assertEquals(expected, actual, delta)</code>", "<code>pytest.approx(left, abs=2)</code>"),
      ("<code>const hits = new Map&lt;string, number&gt;()</code> as the whole limiter", "a <code>ConcurrentHashMap</code> fake", "a <code>dict</code>"),
      ("<code>describe(...)</code> + <code>it(...)</code> over exact violation strings", "<code>assertIterableEquals</code>", "<code>assert violations == [...]</code>")]),
  case("The integration tests stand in for the chaos scripts, not the other way round.",
       "<p><code>crash.int</code> and <code>job-heartbeat.int</code> cover the sweep, the fence and the wipe in seconds, with the crash simulated by a timestamp; <code>kill-worker-resumes</code> and <code>redis-wipe-rebuild</code> do it to the real compose stack with a real <code>SIGKILL</code> and a real <code>FLUSHALL</code>, in minutes. Both exist because they answer different questions: the first, \"is the logic right\"; the second, \"is the wiring right\", including the stub worker running inside the worker image with the compose environment.</p>"),
  case("A timing assertion on the retry, by Postgres's clock.",
       "<p>The chaos script asserts that attempt 2 started at least <code>staleMs</code> after attempt 1's last heartbeat. Both timestamps are read from the row in one <code>psql</code> call and compared with each other, never with the host's clock: a container's clock and the host's may disagree, and a test that compared them would be flaky in exactly the way that hides the bug it looks for.</p>"),
  note("<strong>Honest status, repeated here because it matters:</strong> the unit tests (<code>replay.test</code>, <code>progress.test</code> in the worker and the web, <code>limit.test</code>, <code>usage.test</code>, <code>client-address.test</code>, <code>http-limits.test</code>, <code>rebuild.test</code>, the contracts, the config, the route table in <code>app.test</code>) ran green on every commit. The integration suites (<code>idempotency.int</code>, <code>crash.int</code> including the wipe, <code>job-heartbeat.int</code>, <code>starvation.int</code>, <code>run-progress.int</code>, <code>rate-limit.int</code>, <code>usage.int</code>, <code>http-rate-limit.int</code> with the mint limit), the two end-to-end specs (<code>progress</code>, <code>usage-view</code>) and the two chaos scripts (<code>kill-worker-resumes</code>, <code>redis-wipe-rebuild</code>) are written, reviewed and committed, and have not been run. Section 10 is what running them looks like."))

section("demo", "10 · By hand: press twice, kill the worker, flush Redis, reload mid-run, hit the limit",
  "<p>The exact commands and what each should show. The api is on host port 3000, the web app on 5173; Redis and Postgres are reached through compose. The dev header works in this development stack, which is what lets one terminal act as a person. <code>DOC</code> is a document id from the canvas's <code>?doc=</code>.</p>",
  shell("0 · Bring the stack up",
        "./init.sh                                    # migrate runs 0018 (idempotency_keys), 0019 (heartbeat_at, attempts), 0020 (rate_limits)\n"
        "open http://localhost:5173/                  # sign in, New document; note ?doc=&lt;id&gt;\n"
        "export DOC=&lt;id&gt; H='x-dev-user: you@example.com' J='content-type: application/json'"),
  shell("1 · One key, one job (F27)",
        "K=$(uuidgen)\n"
        "curl -s -H \"$H\" -H \"$J\" -H \"idempotency-key: $K\" -d '{\"instruction\":\"add a hero\"}' localhost:3000/documents/$DOC/runs | jq '{id,status}'   # 201\n"
        "curl -s -H \"$H\" -H \"$J\" -H \"idempotency-key: $K\" -d '{\"instruction\":\"add a hero\"}' localhost:3000/documents/$DOC/runs | jq '{id,status}'   # 201, the SAME id, status as it is now\n"
        "curl -si -H \"$H\" -H \"$J\" -H \"idempotency-key: $K\" -d '{\"instruction\":\"add a footer\"}' localhost:3000/documents/$DOC/runs | head -1        # 422 idempotency_key_reused\n"
        "for i in $(seq 1 10); do curl -s -o /dev/null -w '%{http_code} ' -H \"$H\" -H \"$J\" -H \"idempotency-key: $(uuidgen)\" -d '{\"instruction\":\"x\"}' localhost:3000/documents/$DOC/runs & done; wait   # one 201 (or none: busy), the rest 409: one unfinished run per document\n"
        "docker compose exec -T postgres psql -U noon -d noon -c \"select key, request-&gt;&gt;'queue' as queue, job_id from idempotency_keys\"   # the claimed keys, each naming its job; the 409s left none"),
  shell("2 · Kill the worker mid-run (F28)",
        "docker compose exec -T postgres psql -U noon -d noon -c \"select id, status, attempts, heartbeat_at from jobs where queue = 'ai' order by created_at desc limit 1\"   # running, attempts 1, the beat moving every second\n"
        "docker compose kill -s SIGKILL worker        # nobody says anything\n"
        "watch -n1 'docker compose exec -T postgres psql -U noon -d noon -tAc \"select status, attempts, now() - heartbeat_at from jobs where queue = '\"'\"'ai'\"'\"' order by created_at desc limit 1\"'\n"
        "                                             # running|1|the age growing... past 15 s: worker-ship's or worker-sandbox's sweep requeues it: queued|1|; they do not handle ai, so it waits\n"
        "docker compose start worker                  # its first sweep offers the row; claim: running|2|; the run replays its early steps (nothing added twice) and ends succeeded|2\n"
        "docker compose exec -T postgres psql -U noon -d noon -c \"select count(*), count(distinct op_id), count(distinct op-&gt;&gt;'nodeId') from op_journal where document_id = '$DOC' and actor_kind = 'agent'\"   # three equal numbers"),
  shell("3 · Flush Redis under a waiting run (F28, §4)",
        "docker compose exec -T redis redis-cli --no-auth-warning LLEN bull:ai:wait                 # start a run on a second document while one runs: 1 waiting\n"
        "docker compose exec -T redis redis-cli --no-auth-warning GET lease:$DOC                    # &lt;token&gt;:&lt;node&gt;: the room's owner\n"
        "docker compose exec -T redis redis-cli --no-auth-warning FLUSHALL                          # OK: every key gone, every connection open\n"
        "docker compose exec -T redis redis-cli --no-auth-warning LLEN bull:ai:wait                 # 0, then within 5 s (the sweep) 1 again: offered from Postgres\n"
        "docker compose exec -T postgres psql -U noon -d noon -c \"select status, attempts from jobs where queue = 'ai' order by created_at desc limit 2\"   # both end succeeded, attempts 1: nothing ran twice\n"
        "docker compose exec -T redis redis-cli --no-auth-warning GET lease:$DOC                    # a LARGER token; the canvas blinked once (4409) and is live again\n"
        "docker compose exec -T postgres psql -U noon -d noon -c \"select fence_token from documents where id = '$DOC'\"   # the same token: one owner"),
  shell("4 · Progress, and a reload mid-run (F30)",
        "open http://localhost:5173/?doc=$DOC        # Ask the AI for 'a card with 8 buttons'; the list under the panel grows: Added Card, Added Button...\n"
        "                                             # reload the page while it runs: the same run, the same steps, still running, Cancel still there; after the end, reload again: the list stays\n"
        "curl -s -H \"$H\" localhost:3000/documents/$DOC/run | jq '.run.steps'   # [{tool, ok, detail}...]: the model's argument as text, at most 80 characters\n"
        "docker compose exec -T postgres psql -U noon -d noon -c \"select jsonb_array_length(output-&gt;'steps') from jobs where queue = 'ai' order by created_at desc limit 1\""),
  shell("5 · The limits (F31)",
        "AI_RUNS_PER_HOUR=2 docker compose up -d api  # or edit .env; the default is 60\n"
        "for d in $DOC $DOC2 $DOC3; do curl -si -H \"$H\" -H \"$J\" -d '{\"instruction\":\"x\"}' localhost:3000/documents/$d/runs | grep -i '^HTTP\\|retry-after'; done   # 201, 201, 429 with Retry-After: seconds to the top of the hour\n"
        "curl -s -H \"$H\" -H \"$J\" -d '{\"instruction\":\"x\"}' localhost:3000/documents/$DOC3/runs   # {\"error\":\"rate_limited\",\"retryAfterSeconds\":N}: the same number as the header\n"
        "for i in $(seq 1 305); do curl -s -o /dev/null -w '%{http_code}\\n' localhost:3000/auth/me; done | sort | uniq -c   # 300 x 200, 5 x 429: per address, nobody signed in\n"
        "curl -si -H 'x-forwarded-for: 203.0.113.9' localhost:3000/auth/me | head -1   # 200: from the host, the peer is Docker's gateway (private, trusted in compose), so the header is believed and this is a fresh address\n"
        "docker compose exec -T postgres psql -U noon -d noon -c \"select key, win, hits from rate_limits order by hits desc limit 5\"   # address:..., user:..., ai_run:&lt;org&gt;\n"
        "for i in 1 2 3; do curl -s -o /dev/null -w '%{http_code}\\n' -H \"$J\" -d '{\"email\":\"you@example.com\",\"password\":\"wrong\"}' localhost:3000/auth/signin; done   # 401 x 10, then 429 too_many_attempts with Retry-After (run it eleven times)"),
  shell("6 · Then the checks that prove it without hands",
        "pnpm exec vitest run apps/worker/src/replay.test.ts apps/worker/src/progress.test.ts apps/web/src/progress.test.ts packages/db/src/limit.test.ts apps/api/src/client-address.test.ts apps/api/src/http-limits.test.ts scripts/chaos/rebuild.test.ts   # the pure halves\n"
        "pnpm exec vitest run --config vitest.integration.config.ts apps/api/src/idempotency.int.test.ts apps/worker/src/crash.int.test.ts packages/db/src/job-heartbeat.int.test.ts \\\n"
        "  apps/worker/src/starvation.int.test.ts packages/db/src/run-progress.int.test.ts apps/api/src/rate-limit.int.test.ts packages/db/src/usage.int.test.ts apps/api/src/http-rate-limit.int.test.ts\n"
        "pnpm exec playwright test e2e/progress.spec.ts e2e/usage-view.spec.ts\n"
        "node scripts/chaos/kill-worker-resumes.ts && node scripts/chaos/redis-wipe-rebuild.ts   # against the real stack; each prints one JSON line, exit 0 = PASS\n"
        "make check                                   # the whole gate, as the pre-commit hook runs it"),
  note("<strong>What to do when a step does not match this page:</strong> the page was cut from the code at commit <code>" + commit + "</code>, and the code is right until a test says otherwise. A step that fails is a finding: write it as <em>sequence → false belief → consequence → smallest fix</em> (SPEC §4a's form) and file it against the bead that owns the code."))

section("limits-of-types", "11 · What the type system could not see, epic 9 edition",
  "<p>Everything below compiled under <code>strict</code>, passed the linter and the first tests, or was rejected at design time by asking what the types could not ask.</p>",
  vs([("twenty retries making twenty jobs", "each request is a function call", "a key claimed by a primary key; the loser blocks on the row"),
      ("a look-then-insert for the key", "<code>get_or_create</code> reads fine", "<code>on conflict do nothing</code>: one statement (drill 2)"),
      ("the key as columns on the job", "one table is simpler", "a joined ship has no row to hold it; a table of its own"),
      ("a malformed key silently ignored", "\"optional\" reads as \"skip if bad\"", "400: the retry it protects would not be protected"),
      ("a replay answered from the first response", "the same request, the same answer", "the job's row as it now is"),
      ("a refused run using up its key", "record every outcome", "roll the claim back with the run"),
      ("a key resolving to another tenant's job", "a string is a string", "<code>(org_id, user_id, key)</code>"),
      ("<code>kill -9</code> leaving <code>running</code> for ever", "a promise that never settles has no type", "a heartbeat on the row, a sweep"),
      ("a slow worker finishing over the next attempt", "two <code>UPDATE</code>s look alike", "<code>and attempts = $n</code> in every write"),
      ("a beat that only beats", "one timer, one job", "it also answers cancel and <code>lost</code>"),
      ("two sweeps taking one row", "one statement each", "<code>for update skip locked</code>"),
      ("two stale ships requeued for one document", "each row on its own", "<code>distinct on</code>; 0011 refused the pair"),
      ("a cancelled job run again by the sweep", "stale is stale", "<code>cancel_requested_at</code> ends it as <code>cancelled</code>"),
      ("a dead sandbox's address kept", "output is output", "cleared on requeue; the next attempt reports one"),
      ("a row from before 0019 never judged stale", "<code>heartbeat_at</code> is null", "<code>coalesce(heartbeat_at, started_at)</code>"),
      ("a replayed <code>add_node</code> adding twice", "a new call, a new id", "ids as functions of (job, step)"),
      ("an op id of (job, step) alone", "an id is an id", "the op's content in the hash: a resend for ever otherwise"),
      ("a replay refused instead of done", "<code>duplicate_node</code> is a refusal", "same component under the same parent: done"),
      ("Redis flushed under a running job", "the lock is gone", "nothing: its truth was never in Redis"),
      ("a chaos round that wiped an empty queue", "passed", "vacuity guards: <code>LLEN</code> before the wipe"),
      ("steps from a dead attempt shown", "output is output", "<code>report</code> fenced; cleared on requeue"),
      ("a later list landing before an earlier", "two awaits", "a promise chain; awaited before <code>finish</code>"),
      ("a bidi override in a step's detail", "a string", "<code>\\p{C}</code> stripped; text nodes"),
      ("an older run replacing the one just started", "<code>setRun(latest)</code>", "<code>setRun((current) =&gt; current ?? latest)</code>"),
      ("a row that does not parse throwing on read", "our own worker wrote it", "<code>safeParse</code>; no steps"),
      ("N instances allowing N × the limit", "a counter is a counter", "the count in Postgres"),
      ("a refused run counted", "count then insert", "the hit inside the run's transaction"),
      ("a late hit resetting the window", "<code>win = excluded.win</code>", "<code>greatest</code> and <code>&gt;=</code>"),
      ("<code>now()</code> mid-transaction", "it is \"now\"", "<code>clock_timestamp()</code>"),
      ("a wait of 0 seconds", "rounding down", "<code>Math.max(1, Math.ceil(...))</code>"),
      ("the limiter failing open when Redis is away", "\"allow\" felt kind", "no Redis: Postgres or nothing"),
      ("the probes rate limited", "a route is a route", "never counted"),
      ("a 401 not counted", "nobody to charge", "charged to the address; then 429"),
      ("<code>X-Forwarded-For</code> believed from anyone", "a header is a header", "only past a trusted peer"),
      ("the leftmost entry as the client", "\"the original IP\"", "the rightmost entry a trusted hop vouched for"),
      ("<code>::ffff:127.0.0.1</code> not loopback", "two strings", "<code>unmap</code>"),
      ("a typo in <code>TRUST_PROXY</code> trusting no one", "an empty list", "refuse to start"),
      ("a revoked guest's mints costing a lookup each", "404 is cheap", "<code>mint:</code> charged before the lookup"),
      ("an email too long for the key column", "a string is a string", "its SHA-256")], head=("What went wrong, or would have", "Why", "Fix")),
  note("<strong>The pattern, extended once more:</strong> lesson 8 said types cannot see who is asking or what a value costs. Epic 9 adds the two that make distributed jobs hard: types cannot see <em>how many times</em> a call happens (a function called twice has the same signature as one called once, and a message delivered twice the same shape), and cannot see <em>which clock</em> a number came from (the host's, the container's, the database's, all <code>number</code>). Both were answered as before: put the truth in one place and let the database's own uniqueness and locks do the counting; make every write name the attempt or the claim it belongs to; take the clock from where the truth is; and write a test that provokes the exact case: twenty at once, a timestamp moved into the past, a Lua wipe, a sleep of exactly the promised seconds."))

toc = "".join(f'<li><a href="#{sid}">{title}</a></li>' for sid, title, _ in S)
sections = "".join(f'<section id="{sid}"><h2>{title}</h2>{body}</section>' for sid, title, body in S)
style = re.search(r"<style>.*?</style>", (root / "docs/handbook/lesson-0.template.html").read_text(), re.S).group(0)
page = (pathlib.Path(__file__).parent / "lesson-9.template.html").read_text()
page = page.replace("{{STYLE}}", style).replace("{{TOC}}", toc).replace("{{SECTIONS}}", sections).replace("{{COMMIT}}", commit)
(out / "lesson-9.html").write_text(page)
print("built", len(page), "bytes at", commit, "with", page.count('<p class="label">From'), "code blocks")
